  "cursor/hooks.json": "{\n  \"sessionStart\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook session-start --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 10\n    }\n  ],\n  \"beforeSubmitPrompt\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook user-prompt-submit --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 5\n    }\n  ],\n  \"postToolUse\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook post-tool-use --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 5\n    }\n  ],\n  \"postToolUseFailure\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook post-tool-use-failure --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 5\n    }\n  ],\n  \"stop\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook stop --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 30\n    }\n  ],\n  \"sessionEnd\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook session-end --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 10\n    }\n  ],\n  \"subagentStart\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook subagent-start --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 5\n    }\n  ],\n  \"subagentStop\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook subagent-stop --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 10\n    }\n  ],\n  \"preCompact\": [\n    {\n      \"command\": \"{{mycoLauncher}} hook pre-compact --symbiont cursor\",\n      \"type\": \"command\",\n      \"timeout\": 5\n    }\n  ]\n}\n",
